from django.contrib.auth.decorators import user_passes_test, login_required

def has_no_team(user):
    if user.is_staff:
        return True
    if user.team_set.all().count() == 0:
        return True
    return False

has_no_team_test = user_passes_test(has_no_team)


def has_no_team_required(view_func):
    decorated_view_func = login_required(has_no_team_test(view_func))
    return decorated_view_func

def has_team(user):
    if user.is_staff:
        return True
    if user.team_set.all().count() >= 1:
        return True
    return False


