class pep257Checker(object):

    """flake8 needs a class to check python file."""

    name = 'flake8-docstrings'
    version = __version__ + ', pep257:' + pep8.__version__

    def __init__(self, tree, filename='(none)', builtins=None):
        # Ripped form flake8 import pep8
        if no_docstring_re.search(filename):
            self.filename = filename
        else:
            self.filename = None
        self.tree = tree
        self.ignored = True if filename in pep8.options.ignore else False

    if pep8.PEP257Error:
        def run(self):
            """Use directly check() api from pep257."""
            if self.filename and not self.ignored:
                for error in pep8.check()[1]:
                    # Ignore AllError, Environment error.
                    if isinstance(error, pep8.PEP257Error):
                        yield (error.line, 0, error.message, type(self))
    else:
        def run(self):
            """Use directly check() api from pep257."""
            if self.filename and not self.ignored:
                for error in pep8.check_dir([self.filename])[1]:
                    # Ignore AllError, Environment error.
                    if isinstance(error, pep8.PEP257Error):
                        yield (error.line, 0, error.message, type(self))


